import { wrap, shadow, ref, text } from '../style.mjs';

// Redraws of five diet citrus and ginger soda cans marked Needs work in the 2026-11-15
// review (redraw round 2). The rejected recipes were in refreshments-12.mjs (template
// cans with the brand typed in Arial). Each can here is drawn from the current US
// 12 fl oz packshot; four of the five brands now print ZERO SUGAR where the catalog
// still says Diet, and the records say so.
//
// This file is generated: the traced path constants below are inlined by
// scratchpad/agents2/citrus/work/build.mjs from module.src.mjs. It is complete and
// self-contained; nothing is read at build time.
//
// Traced marks. The Squirt, Sunkist, Crush and Vernors logotypes are not constructed by
// hand: each was segmented by color from the packshot named in its
// record, and its outlines fitted with cubic Beziers by a short script, in the packshot's
// own projection (letters near the can edge are foreshortened as they are on the can).

const r2 = n => Math.round(n * 100) / 100;

// Standard 12 fl oz can: geometry and rendering copied from the Good `can()` helper in
// classic-soda-expansion.mjs (canada-dry-ginger-ale, barqs-root-beer): l=55 r=145 t=41 b=229.
const BODY = 'M61 41Q100 32 139 41L145 58V220Q145 233 100 233T55 220V58Z';
const drops = Array.from({ length: 18 }, (_, i) => `<ellipse cx="${65 + (i * 19) % 70}" cy="${65 + (i * 31) % 148}" rx="${i % 3 === 0 ? 1.2 : .7}" ry="${i % 3 === 0 ? 1.8 : 1}" fill="#fff" opacity=".28"/>`).join('');
const WHITE_CAN = `<linearGradient id="__ID__body"><stop stop-color="#b9bcbb"/><stop offset=".17" stop-color="#f3f3f0"/><stop offset=".42" stop-color="#fdfdfb"/><stop offset=".68" stop-color="#eeeeeb"/><stop offset=".87" stop-color="#c2c5c4"/><stop offset="1" stop-color="#dcdedc"/></linearGradient>`;
function can(slug, title, label, { color = ref('body'), defs = WHITE_CAN, wet = false, under = '' } = {}) {
  return wrap(slug, title, `${shadow(58)}<path d="${BODY}" fill="${color}"/><g clip-path="${ref('bodyclip')}">${under}${label}<path d="${BODY}" fill="${ref('shade')}"/>${wet ? drops : ''}<path d="M65 61V211" fill="none" stroke="#fff" stroke-opacity=".21" stroke-width="3"/></g><ellipse cx="100" cy="41" rx="39" ry="8" fill="${ref('metal')}" stroke="#9ca7a4" stroke-width="1.2"/><ellipse cx="100" cy="41" rx="34" ry="5.5" fill="none" stroke="#8d9892" stroke-width=".8"/><ellipse cx="104" cy="42" rx="8" ry="3.5" fill="#657169"/><path d="M93 39h10q6 0 5 4t-8 3h-6q-6-1-1-7" fill="none" stroke="#e6e8de" stroke-width="2.4"/><path d="M58 226q42 12 84 0" fill="none" stroke="${ref('metal')}" stroke-width="4"/><path d="M61 230q39 7 78 0" fill="none" stroke="#fff" stroke-opacity=".55" stroke-width="1"/>`, `<clipPath id="__ID__bodyclip"><path d="${BODY}"/></clipPath>${defs}`);
}

// A printed band across the can front. Edges are given at the can side and at the centre:
// on the packshots the band sags towards the centre, more at its lower edge.
const band = (te, tc, be, bc, fill) => `<path d="M50 ${te}Q100 ${r2(2 * tc - te)} 150 ${te}V${be}Q100 ${r2(2 * bc - be)} 50 ${be}Z" fill="${fill}"/>`;
// Lettering traced from a packshot and normalised to width 100, baseline 0, centred on x=0.
const lettering = (d, cx, base, width, fill) => `<path transform="translate(${cx} ${base}) scale(${r2(width / 100)})" d="${d}" fill="${fill}" fill-rule="evenodd"/>`;
