const CAN_R = 47.6;
function zeroSugar(x0, x1, base, capH, fill, lift = 0) {
  const k = capH / 10, s0 = CAN_R * Math.asin((x0 - 100) / CAN_R), s1 = CAN_R * Math.asin((x1 - 100) / CAN_R);
  const natural = ZERO_SUGAR.reduce((n, l) => n + (l.w + l.gap) * k, 0);
  const track = (s1 - s0 - natural) / (ZERO_SUGAR.length - 1);
  let s = s0, out = '';
  ZERO_SUGAR.forEach((l, i) => {
    if (i) s += l.gap * k + track;
    const mid = s + l.w * k / 2, x = 100 + CAN_R * Math.sin(mid / CAN_R), sx = Math.cos(mid / CAN_R);
    const y = base - lift * ((x - 100) / ((x1 - x0) / 2)) ** 2;
    out += `<path transform="translate(${r2(x)} ${r2(y)}) scale(${r2(k * sx)} ${r2(k)}) translate(${r2(-l.w / 2)} 0)" d="${l.d}"/>`;
    s += l.w * k;
  });
  return `<g fill="${fill}" fill-rule="evenodd">${out}</g>`;
}
const rot = (x, y, deg, inner) => `<g transform="translate(${x} ${y}) rotate(${deg})">${inner}</g>`;

