function crush() {
  const slug = 'diet-orange-crush', title = 'Diet Orange Crush';
  const ORANGE = '#f8611a', LIGHT = '#f9a024', CREAM = '#ffe6b8', MINT = '#84dfb2', VEIN = '#27a05c', GREEN = '#04933b';
  // The fruit pattern is constructed from positions measured on the packshot (its pixel
  // grid, 1000 x 2000); X/Y map that grid onto the can.
  const X = x => r2(52 + x * .096), Y = y => r2(40 + y * .096), K = .096;
  const orange = ([cx, cy, rx, ry]) => `<ellipse cx="${X(cx)}" cy="${Y(cy)}" rx="${r2(rx * K)}" ry="${r2(ry * K)}"/>`;
  // Almond leaf from its stem end to its tip, `hw` half-width, with a midrib.
  const leafD = ([x1, y1, x2, y2, hw]) => {
    const mx = (x1 + x2) / 2, my = (y1 + y2) / 2, len = Math.hypot(x2 - x1, y2 - y1), nx = -(y2 - y1) / len, ny = (x2 - x1) / len;
    const bx = x1 + (x2 - x1) * .38, by = y1 + (y2 - y1) * .38;
    return `M${X(x1)} ${Y(y1)}Q${X(bx + nx * hw * 2.3)} ${Y(by + ny * hw * 2.3)} ${X(x2)} ${Y(y2)}Q${X(bx - nx * hw * 2.3)} ${Y(by - ny * hw * 2.3)} ${X(x1)} ${Y(y1)}Z`;
  };
  const ribD = ([x1, y1, x2, y2, hw]) => {
    const len = Math.hypot(x2 - x1, y2 - y1), nx = -(y2 - y1) / len, ny = (x2 - x1) / len, f = t => [x1 + (x2 - x1) * t, y1 + (y2 - y1) * t];
    const [ax, ay] = f(.12), [bx, by] = f(.8), [cx, cy] = f(.45);
    return `M${X(ax)} ${Y(ay)}Q${X(cx + nx * hw * .22)} ${Y(cy + ny * hw * .22)} ${X(bx)} ${Y(by)}`;
  };
  // Cut face: the half of an orange on one side of a chord through its centre.
  const face = ([cx, cy, rx, ry], deg, flip) => {
    const a = deg * Math.PI / 180, pt = (t, f = 1) => `${X(cx + rx * f * Math.cos(t))} ${Y(cy + ry * f * Math.sin(t))}`, sw = flip ? 0 : 1;
    const half = f => `M${pt(a, f)}A${r2(rx * K * f)} ${r2(ry * K * f)} 0 0 ${sw} ${pt(a + Math.PI, f)}`;
    const dir = flip ? -1 : 1;
    const spokes = [30, 60, 90, 120, 150].map(d => { const t = a + dir * d * Math.PI / 180; return `M${pt(t, .2)}L${pt(t, .8)}`; }).join('');
    const star = Array.from({ length: 10 }, (_, i) => { const t = a + i * Math.PI / 5; return `${i ? 'L' : 'M'}${pt(t, i % 2 ? .07 : .17)}`; }).join('') + 'Z';
    return `<path d="${half(1)}Z" fill="${LIGHT}"/><path d="${half(.86)}" fill="none" stroke="${CREAM}" stroke-width=".55"/><path d="${spokes}" fill="none" stroke="${CREAM}" stroke-width=".45" stroke-linecap="round"/><path d="${star}" fill="${CREAM}"/>`;
  };
  const O1 = [507, 405, 128, 128], O2 = [855, 300, 93, 132], O3 = [772, 500, 66, 97], O4 = [118, 495, 115, 158], O5 = [162, 1755, 95, 95], O6 = [840, 1757, 130, 155];
  const oranges = [O1, O2, O3, O4, O5, O6, [30, 1415, 78, 125], [20, 1850, 55, 70], [1000, 1365, 36, 75], [5, 265, 36, 70], [1000, 360, 25, 50]];
  const back = [[268, 272, 128, 102, 58], [75, 350, 222, 303, 32], [232, 445, 330, 548, 36], [30, 380, 20, 580, 26], [800, 230, 685, 70, 55], [845, 170, 858, 100, 22], [995, 560, 958, 645, 20], [925, 1445, 990, 1590, 36], [800, 1615, 655, 1550, 38], [245, 1705, 410, 1800, 48], [190, 1840, 245, 1880, 22], [15, 1770, 62, 1810, 20], [55, 1520, 130, 1515, 22]];
  const front = [[632, 405, 495, 185, 62], [800, 400, 885, 520, 36], [1000, 1290, 920, 1315, 28], [185, 1565, 205, 1675, 30], [205, 1565, 280, 1645, 24]];
  const stems = `M${X(632)} ${Y(405)}Q${X(700)} ${Y(400)} ${X(775)} ${Y(355)}M${X(850)} ${Y(175)}Q${X(848)} ${Y(110)} ${X(832)} ${Y(60)}M${X(930)} ${Y(390)}Q${X(945)} ${Y(450)} ${X(990)} ${Y(500)}M${X(95)} ${Y(1660)}Q${X(110)} ${Y(1590)} ${X(165)} ${Y(1565)}L${X(205)} ${Y(1562)}M${X(40)} ${Y(1540)}Q${X(5)} ${Y(1650)} ${X(20)} ${Y(1750)}M${X(60)} ${Y(330)}Q${X(20)} ${Y(360)} ${X(8)} ${Y(420)}`;
  const leaves = list => `<path d="${list.map(leafD).join('')}" fill="${MINT}"/><path d="${list.map(ribD).join('')}" fill="none" stroke="${VEIN}" stroke-width=".5" stroke-linecap="round"/>`;
  const fruit = `<path d="${stems}" fill="none" stroke="${MINT}" stroke-width="1.2" stroke-linecap="round"/>${leaves(back)}<g fill="${ORANGE}">${oranges.map(orange).join('')}</g><g clip-path="${ref('fruit')}"><path d="${back.map(leafD).join('')}" fill="#c8380a" opacity=".55"/></g>${face(O2, 52, true)}${face(O4, 47, false)}${face(O6, -23.7, true)}${leaves(front)}`;
  const script = `<path d="${CRUSH_SCRIPT}" fill="${MINT}" fill-rule="evenodd" transform="translate(-.75 .6)"/><path d="${CRUSH_SCRIPT}" fill="#008a35" fill-rule="evenodd"/>`;
  const wordmark = `<path d="${CRUSH_ORANGE}" fill="${ORANGE}"/><path d="${CRUSH_GREEN}" fill="${ref('extrude')}"/><path d="${CRUSH_FACES}" fill="#fcfcf9" stroke="${GREEN}" stroke-width=".4" stroke-linejoin="round"/><path d="${CRUSH_INLINE}" fill="none" stroke="#f47a45" stroke-width=".24" stroke-linejoin="round"/>`;
  const label = `${band(164.6, 165.5, 174.6, 175.7, GREEN)}${zeroSugar(70.2, 129.3, 174, 6.1, '#fff', .5)}${fruit}${wordmark}${script}`;
  const defs = `${WHITE_CAN}<clipPath id="__ID__fruit">${oranges.map(orange).join('')}</clipPath><linearGradient id="__ID__extrude" gradientUnits="userSpaceOnUse" x1="0" y1="102" x2="0" y2="152"><stop stop-color="#36c276"/><stop offset=".5" stop-color="#0c9a47"/><stop offset="1" stop-color="#047a35"/></linearGradient>`;
  return {
    slug, family: 'crush-soda-can',
    packageChoice: 'Current US 12 fl oz can of Crush Zero Sugar Orange, the product the catalog row "Diet Orange Crush" now maps to (Diet Crush was renamed Crush Zero Sugar; the current can prints ZERO SUGAR, not diet).',
    references: [{
      pageUrl: 'https://www.crushsoda.com/',
      imageUrl: 'https://s7d1.scene7.com/is/image/kdrp/CR_Orange_ZeroSugar_12oz_Can_Wet?$Dynamic-PublicURL-PNG$&wid=1000&hei=2000',
      inspectedAt: '2026-11-15', visuallyInspected: true,
      observations: 'Manufacturer front packshot (Keurig Dr Pepper image server; crushsoda.com lists the same product as Crush Zero Sugar Orange in a 20 oz bottle): silver-white 12 fl oz can scattered with flat orange discs, three of them cut to show a lighter face with cream segments, and mint-green leaves and stems; the Crush wordmark in white letters with a thin green outline and thin orange inline, extruded down and right in green and then orange, arching across the whole front; "Orange" in a green script with a mint shadow under the sh; a green band reading ZERO SUGAR in white, widely tracked.',
    }, {
      pageUrl: 'https://www.kroger.com/p/diet-crush-orange-soda-cans/0007800001390',
      imageUrl: 'https://www.kroger.com/product/images/xlarge/front/0007800001390',
      inspectedAt: '2026-11-15', visuallyInspected: true,
      observations: 'The retailer listing the rejected batch recorded, opened at the larger size: a 12-pack carton of the older Diet Crush design (white carton, red-orange splash, white Crush with a green outline, "diet" in green script, an orange slice, "no calorie orange soda"). Historical design, and a carton rather than a can; not drawn.',
    }],
    uncertainty: 'The wordmark is traced; the fruit, leaves and stems are constructed from measured positions and are simpler than the printed pattern (leaf side veins and the smallest slivers at the can edge are left out, and where a leaf passes behind an orange the darker overlap is approximate). The thin outlines between adjoining letters of the wordmark are not drawn. Condensation and the registered mark are omitted. The catalog name says Diet; the can drawn says ZERO SUGAR because that is what the current US can prints.',
    status: 'needs-review',
    svg: can(slug, title, label, { defs }),
  };
}

